   System.out.println(winMessage); 
} else {
   if (comeOutRoll == 11) {
      System.out.println(winMessage);
   } else {
      if (comeOutRoll == 2) {
         System.out.println(loseMessage);
      } else {
         if (comeOutRoll == 3) {
            System.out.println(loseMessage);
         } else {
            if (comeOutRoll == 12) {
               System.out.println(loseMessage);
            } else {
               System.out.println(continueMessage);
            }
         }
      }
   }
}
</code></pre> <p>The fully nested version is shown here only as a learning aid — it precisely mirrors the execution  logic. But once this has been seen, the behavior of a conventionally formatted <code>if</code>-<code>else</code> chain is  easy to understand.</p>

